mkdir -p /tmp/fbench && cp go.mod /tmp/fbench/ && mkdir -p /tmp/fbench/parser && cp parser/parser.go /tmp/fbench/parser/ && cat > /tmp/fbench/parser/b_test.go <<'EOF'
package parser

import ("strings"; "testing"; "reflect")

var sink []string
var lines = map[string]string{
	"short": "a,b,c,d",
	"typical": "1042,alice@example.com,Alice Smith,2026-10-08,49.99,USD,shipped",
	"long": strings.Repeat("field,", 200) + "end",
}

func TestSame(t *testing.T) {
	for _, l := range []string{"", ",", "a", "a,,b,", lines["long"]} {
		if !reflect.DeepEqual(Fields(l), strings.Split(l, ",")) { t.Fatalf("mismatch %q", l) }
	}
}
func BenchmarkFields(b *testing.B) {
	for name, l := range lines {
		b.Run(name+"/new", func(b *testing.B) { b.ReportAllocs(); for i := 0; i < b.N; i++ { sink = Fields(l) } })
		b.Run(name+"/split", func(b *testing.B) { b.ReportAllocs(); for i := 0; i < b.N; i++ { sink = strings.Split(l, ",") } })
	}
}
EOF
cd /tmp/fbench && go version && go test ./parser -run TestSame -bench=Fields -count=5 2>&1 | tail -40

